use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " What to do when a node is examined or becomes `Settled` during DFS."] pub trait TriColorVisitor < G > where G : ? Sized + DirectedGraph , { # [doc = " The value returned by this search."] type BreakVal ; # [doc = " Called when a node is examined by the depth-first search."] # [doc = ""] # [doc = " By checking the value of `prior_status`, this visitor can determine whether the edge"] # [doc = " leading to this node was a tree edge (`None`), forward edge (`Some(Settled)`) or back edge"] # [doc = " (`Some(Visited)`). For a full explanation of each edge type, see the \"Depth-first Search\""] # [doc = " chapter in [CLR] or [wikipedia]."] # [doc = ""] # [doc = " If you want to know *both* nodes linked by each edge, you'll need to modify"] # [doc = " `TriColorDepthFirstSearch` to store a `source` node for each `Visited` event."] # [doc = ""] # [doc = " [wikipedia]: https://en.wikipedia.org/wiki/Depth-first_search#Output_of_a_depth-first_search"] # [doc = " [CLR]: https://en.wikipedia.org/wiki/Introduction_to_Algorithms"] fn node_examined (& mut self , _node : G :: Node , _prior_status : Option < NodeStatus > ,) -> ControlFlow < Self :: BreakVal > { ControlFlow :: Continue (()) } # [doc = " Called after all nodes reachable from this one have been examined."] fn node_settled (& mut self , _node : G :: Node) -> ControlFlow < Self :: BreakVal > { ControlFlow :: Continue (()) } # [doc = " Behave as if no edges exist from `source` to `target`."] fn ignore_edge (& mut self , _source : G :: Node , _target : G :: Node) -> bool { false } }